    /** @return list<array{slug: string, title: string, category: string, summary: string, body: string, sources: list<array{0: string, 1: string}>}> */
    public static function all(): array
    {
        return [
            ['slug' => 'what-is-an-out-of-area-referral', 'title' => 'What is an out-of-area referral?', 'category' => 'Referral basics',
                'summary' => 'An out-of-area referral is when a pro passes a client who needs help in another city to a trusted pro there, with the client’s consent, so the client is served well and the referring pro stays involved.',
                'body' => '<h2>Why they happen</h2><p>Clients move, buy second homes, or need a service far from where you work. Most pros can only serve their own area, often because their license is limited to one state. Without a trusted contact in the other city, that client is simply lost.</p><h2>How a good referral works</h2><ol><li><strong>Ask the client first.</strong> Explain who you would like to introduce them to, and why.</li><li><strong>Send the details once they agree.</strong> Include what the client needs and when.</li><li><strong>The receiving pro responds quickly</strong>, accepts or declines, and contacts the client.</li><li><strong>Both sides stay informed</strong> until the work is done or the client decides not to go ahead.</li></ol><h2>What makes it work</h2><p>Trust. You are lending your reputation to someone else, so it matters that they are verified, responsive and keep you updated. That is why networks with one vetted pro per city, clear deadlines and a shared timeline make referrals more reliable than an ad-hoc phone call.</p>',
                'sources' => []],

            ['slug' => 'how-real-estate-referral-fees-work', 'title' => 'How do real estate referral fees work?', 'category' => 'Referral fees',
                'summary' => 'A real estate referral fee is a share of the receiving agent’s commission paid to the referring agent when the deal closes; about 25% is common but it is negotiable, and it is generally paid only between licensed agents and brokers.',
                'body' => '<h2>The basic arrangement</h2><p>When you refer a buyer or seller to an agent in another market, you agree a fee up front. If the client closes with that agent, the receiving side pays you a share of the commission it earns. The fee comes out of the commission, not out of the client’s pocket.</p><h2>How much?</h2><p>There is no set rate. Industry guides and a 2020 Consumer Federation of America report describe about one quarter of the receiving agent’s commission as the most common figure, with fees above and below that by negotiation.</p><h2>Is it legal?</h2><p>Federal rules under RESPA generally ban payments for referring settlement-service business, but the CFPB’s Regulation X specifically allows cooperative brokerage and referral arrangements between real estate agents and brokers. State license law usually adds that the fee must go to a licensed agent or broker, typically paid broker to broker. Check your own state’s rules and your broker’s policy.</p><h2>Put it in writing</h2><p>Agree the percentage, how long the agreement lasts and when payment is due before you send the client. On Team to Team Referrals the fee is always a share of what the receiving team earns, never of the sale price, and the money passes directly between the two teams.</p>',
                'sources' => [['Regulation X §1024.14: Prohibition against kickbacks and unearned fees (CFPB)', 'https://www.consumerfinance.gov/rules-policy/regulations/1024/14/'],
                    ['RESPA (National Association of REALTORS)', 'https://www.nar.realtor/RESPA'],
                    ['Real Estate Referral Fees report, September 2020 (Consumer Federation of America)', 'https://consumerfed.org/wp-content/uploads/2020/09/Real-Estate-Referral-Fees-Report-9-21-20.pdf']]],

            ['slug' => 'can-mortgage-lenders-pay-referral-fees', 'title' => 'Can mortgage lenders pay referral fees? RESPA Section 8 explained', 'category' => 'Referral fees',
                'summary' => 'No. Under RESPA Section 8 and the CFPB’s Regulation X, no one may give or accept a fee or anything of value for referring settlement-service business on a federally related mortgage loan; a referral itself is not a payable service.',
                'body' => '<h2>What the rule says</h2><p>Regulation X, which carries out Section 8 of the Real Estate Settlement Procedures Act, forbids giving or accepting any fee, kickback or other thing of value under an agreement or understanding to refer settlement-service business connected with a federally related mortgage loan. It also states plainly that referring business is not a service you can be paid for.</p><h2>Who it covers</h2><p>Settlement services include mortgage lending, title and settlement work, and other services in a home purchase financed with such a loan. That is why on Team to Team Referrals these industries are restricted: referrals are exchanged without any payment.</p><h2>What is still allowed</h2><p>The rule permits payment for goods or services actually provided at a fair value, and it keeps the exception for referral fees between real estate agents and brokers. It does not allow dressing up a referral payment as something else.</p><h2>Why refer at all, then?</h2><p>Because your client gets a professional you trust. On our network, members in these industries earn recognition and credits that have no cash value.</p><p><em>This is general information, not legal advice. Ask your compliance team or attorney about your situation.</em></p>',
                'sources' => [['Regulation X §1024.14: Prohibition against kickbacks and unearned fees (CFPB)', 'https://www.consumerfinance.gov/rules-policy/regulations/1024/14/'],
                    ['12 CFR §1024.14 (Legal Information Institute, Cornell Law School)', 'https://www.law.cornell.edu/cfr/text/12/1024.14']]],

            ['slug' => 'what-is-a-thing-of-value-under-respa', 'title' => 'What counts as a “thing of value” under RESPA?', 'category' => 'Referral fees',
                'summary' => 'Under RESPA almost anything can be a thing of value: money, discounts, gifts, trips, paying someone’s expenses or special rates. Giving one in return for settlement-service referrals is prohibited, whatever its size.',
                'body' => '<h2>A deliberately broad definition</h2><p>Regulation X lists examples including money, discounts, salaries, commissions, fees, stock, trips, payment of another person’s expenses and sales or rentals at special prices. A payment does not have to be cash.</p><h2>No size exception</h2><p>The CFPB’s 2020 answers to common Section 8 questions say gifts given in exchange for referrals are prohibited, with no exception based on how small the gift is. Normal promotional and educational activities that are not tied to referrals are treated differently.</p><h2>An understanding can be unwritten</h2><p>The regulation says an agreement to refer does not need to be written or spoken; a pattern of conduct can establish it, especially when something of value keeps arriving in step with the business referred.</p><h2>On our network</h2><p>Credits and badges in restricted industries are recognition only: they cannot be exchanged for money, discounts or anything else.</p><p><em>General information, not legal advice.</em></p>',
                'sources' => [['Regulation X §1024.14 (CFPB)', 'https://www.consumerfinance.gov/rules-policy/regulations/1024/14/'],
                    ['CFPB issues RESPA Section 8 FAQs, October 2020 (Consumer Finance Monitor, Ballard Spahr)', 'https://www.consumerfinancemonitor.com/2020/10/08/cfpb-issues-respa-section-8-faqs-and-rescinds-2015-marketing-services-agreement-bulletin/']]],

            ['slug' => 'how-fast-should-you-respond-to-a-referral', 'title' => 'How fast should you respond to a referral?', 'category' => 'Working referrals',
                'summary' => 'Within the hour if you can. A Harvard Business Review study found firms that contacted a new lead within an hour were nearly seven times as likely to qualify it as firms that waited longer, yet most responded far more slowly.',
                'body' => '<h2>What the research found</h2><p>For “The Short Life of Online Sales Leads” (Harvard Business Review, March 2011), researchers sent inquiries to more than two thousand US companies. Many took more than a day to respond or never responded, while those who replied within an hour did far better at qualifying the lead.</p><h2>Why referrals are even more time-sensitive</h2><p>A referred client was promised someone dependable. A slow first call reflects on the person who referred them, not just on you.</p><h2>Practical habits</h2><ul><li>Turn on notifications for new referrals.</li><li>Accept or decline as soon as you can; a quick “no” lets the sender find someone else.</li><li>Make first contact the same day, and tell the referring pro when you have.</li></ul><p>On Team to Team Referrals each network sets its own deadlines, and reminders arrive before they pass, never after.</p>',
                'sources' => [['The Short Life of Online Sales Leads, March 2011 (Harvard Business Review)', 'https://hbr.org/2011/03/the-short-life-of-online-sales-leads'],
                    ['Oldroyd, McElheran and Elkington (2011), record (BYU ScholarsArchive)', 'https://scholarsarchive.byu.edu/facpub/9711']]],

            ['slug' => 'getting-client-consent-before-a-referral', 'title' => 'How do you get a client’s consent before referring them?', 'category' => 'Working referrals',
                'summary' => 'Ask clearly before sharing anything: say who you want to introduce them to and why, and get a yes. Texting a client for marketing has its own federal consent rules, so keep messages about their request.',
                'body' => '<h2>Ask, then share</h2><p>Tell the client the name of the pro and the city, what you will pass on (name, contact details, what they need) and that they can say no. Only send the referral once they agree.</p><h2>Text messages</h2><p>Under the Telephone Consumer Protection Act, the FCC treats text messages like calls. Marketing texts sent with automated tools generally need the person’s prior express written consent, and texts are covered by the Do Not Call rules as well. Messages that simply follow up on a client’s own request are treated differently, but keep them about that request.</p><h2>How we handle it</h2><p>When you send a referral you confirm the client agreed; the client can also confirm by text or link. Their details reach the receiving pro only after the referral is accepted.</p><p><em>General information, not legal advice.</em></p>',
                'sources' => [['FCC adopts new TCPA rules for lead-generated communications, January 2024 (Cooley)', 'https://www.cooley.com/news/insight/2024/2024-01-09-fcc-adopts-new-tcpa-rules-for-lead-generated-communications']]],

            ['slug' => 'what-to-put-in-a-referral-agreement', 'title' => 'What should a referral agreement include?', 'category' => 'Referral fees',
                'summary' => 'A referral agreement should name both parties and the client, state the fee and how it is worked out, how long the agreement lasts, and when and how the fee is paid once the deal closes.',
                'body' => '<h2>The essentials</h2><ul><li><strong>Who:</strong> the referring and receiving parties, and the client.</li><li><strong>The fee:</strong> a percentage of what the receiving party earns, or a flat amount.</li><li><strong>How long it lasts:</strong> for example, transactions within 12 months.</li><li><strong>When it is paid:</strong> usually within a set number of days after closing.</li><li><strong>Signatures and date.</strong></li></ul><p>Industry guides list the same core points: the agreed rate, an expiry date and the conditions for payment.</p><h2>In restricted industries</h2><p>Where fees are not allowed, the agreement should say plainly that no payment will be made for the referral.</p><h2>On our network</h2><p>Every referral can carry an e-signed agreement with these terms filled in from the network’s rules, and a copy goes to both parties.</p>',
                'sources' => [['Real estate referral fees, a guide (HousingWire)', 'https://housingwire.com/articles/real-estate-referral-fees']]],

            ['slug' => 'how-to-choose-a-pro-in-another-city', 'title' => 'How do you choose a trustworthy pro in another city?', 'category' => 'Referral basics',
                'summary' => 'Look for a verified license, a record of fast responses and regular updates, and clear rules on fees and consent. Track records of how they treat referrals matter more than advertising.',
                'body' => '<h2>Checks that matter</h2><ol><li><strong>License:</strong> for licensed work, confirm it is active in that state.</li><li><strong>Responsiveness:</strong> how quickly do they accept and contact clients?</li><li><strong>Updates:</strong> will you hear how it is going without chasing?</li><li><strong>Closing rate:</strong> do referred clients actually get served?</li><li><strong>Clear terms:</strong> any fee agreed in writing, before you send the client.</li></ol><h2>How the network helps</h2><p>Each member’s license is verified and their trust score summarizes the last 12 months: response speed, updates, conversion, fee reliability and accurate outcomes. New members show as “New” until they have a track record.</p>',
                'sources' => []],

            ['slug' => 'referral-fees-outside-real-estate', 'title' => 'Are referral fees allowed in home services like solar or moving?', 'category' => 'Referral fees',
                'summary' => 'Often yes: RESPA’s ban covers settlement services tied to federally related mortgages, not most home services, but state licensing rules and each industry’s own rules still apply, so check before you agree a fee.',
                'body' => '<h2>Where the RESPA ban applies</h2><p>Section 8 of RESPA targets referral payments for settlement services connected with federally related mortgage loans, such as lending and title work. Many home services, like solar installation or moving, are outside that scope.</p><h2>Other rules still matter</h2><p>Some trades are licensed by the state, and licensing boards can restrict paying unlicensed people for referrals. Professional bodies may have their own rules. When in doubt, ask your licensing board or an attorney.</p><h2>How the network decides</h2><p>Every industry on Team to Team Referrals has a compliance tier. Where fees are allowed, they are always a share of what the receiving team earns, agreed up front and paid directly between teams.</p><p><em>General information, not legal advice.</em></p>',
                'sources' => [['Regulation X §1024.14 (CFPB)', 'https://www.consumerfinance.gov/rules-policy/regulations/1024/14/']]],

            ['slug' => 'how-client-details-are-kept-private', 'title' => 'How are client details kept private in a referral network?', 'category' => 'Referral basics',
                'summary' => 'On Team to Team Referrals a client’s details are shared only after the client agrees and the receiving pro accepts; until then the receiving pro sees what is needed, never contact details.',
                'body' => '<h2>Step by step</h2><ol><li>The referring pro confirms the client agreed to be referred.</li><li>The receiving pro sees the request without contact details and accepts or declines.</li><li>Only after acceptance are the client’s name, phone and email shared.</li></ol><h2>Other protections</h2><ul><li>Messages between teams hide phone numbers and emails until the referral is accepted.</li><li>Reports and exports use short names, never contact details.</li><li>Staff can see full details only for a support case, with a stated reason that is logged.</li><li>Where AI features are switched on, client phone numbers and email addresses are masked before anything is sent to the AI provider.</li></ul>',
                'sources' => []],
        ];
    }
}
